body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 20px;
    background-color: #f4f4f4;
}

#main-container {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    gap: 20px;
    max-width: 1400px;
    margin: 0 auto;
}

#visualization {
    flex: 2;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

#details {
    flex: 1;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 0 10px rgba(0,0,0,0.1);
    max-height: 90vh;
    overflow-y: auto;
}

#bubble-chart {
    width: 100%;
    height: 700px;
    position: relative;
}

circle {
    cursor: pointer;
    transition: all 0.2s;
}

circle:hover {
    stroke: #000;
    stroke-width: 2px;
}

circle.highlighted {
    stroke: #000;
    stroke-width: 3px;
    fill-opacity: 1;
}

circle.dimmed {
    fill-opacity: 0.3;
}

text.bubble-label {
    pointer-events: none;
    font-size: 10px;
    fill: #333;
    text-anchor: middle;
}

#table-container {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    padding: 10px;
    text-align: left;
    border-bottom: 1px solid #ddd;
}

th {
    background-color: #f8f8f8;
    position: sticky;
    top: 0;
}

tr:hover {
    background-color: #f1f1f1;
    cursor: pointer;
}

tr.selected {
    background-color: #e0e0e0;
    font-weight: bold;
}

.tooltip {
    position: absolute;
    text-align: center;
    padding: 8px;
    font: 12px sans-serif;
    background: rgba(0, 0, 0, 0.8);
    color: white;
    border-radius: 4px;
    pointer-events: none;
    z-index: 100;
}

#legends {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 10px;
}

.legend-item {
    display: flex;
    align-items: center;
    font-size: 12px;
}

.legend-color {
    width: 12px;
    height: 12px;
    margin-right: 5px;
    border-radius: 2px;
}

